import { expectStatus, expect, test, uniqueName, USERS, PASSWORD } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "search ignores case and matches part of a name",
    { tag: "@LIF-13" },
    async ({ apiAs, factory }) => {
      // Arrange
      const member = await apiAs("member");
      const name = uniqueName("Zephyrine Cold Storage");
      const vendor = await factory.vendor({ name });

      // Act
      const response = await member.get("/api/vendors", {
        params: { q: "COLD stor", limit: 100 },
      });

      // Assert
      const page = await expectStatus<{ items: { id: string; name: string }[] }>(response, 200);
      const ids = page.items.map((v) => v.id);
      expect(ids).toContain(vendor.id);
    },
  );
});
